insert into public.categories (slug, name, sort_order) values ('pantry','Pantry',1),('drinks','Drinks',2),('snacks','Snacks',3),('household','Household',4) on conflict (slug) do nothing;
insert into public.store_sections (slug, name, category_id, sort_order) select slug, name, id, sort_order from public.categories on conflict (slug) do nothing;
with p as (insert into public.products (slug, name, description, category_id, status, is_mock, published_at) select 'olive-oil', 'Extra Virgin Olive Oil', 'Extra Virgin Olive Oil. Development sample product.', id, 'published', true, now() from public.categories where slug='pantry' on conflict (slug) do nothing returning id), v as (insert into public.product_variants (product_id, sku, name, sort_order) select p.id, x.sku, x.name, x.ord from p, (values ('MOCK-OLIVE-OIL-1','500 ml',1), ('MOCK-OLIVE-OIL-2','1 L',2)) as x(sku, name, ord) returning id, sku), pr as (insert into public.variant_prices (variant_id, currency, amount) select v.id, c.cur, x.price from v join (values ('MOCK-OLIVE-OIL-1',899), ('MOCK-OLIVE-OIL-2',1499)) as x(sku, price) using (sku) cross join (values ('EUR'),('USD')) as c(cur)) insert into public.inventory (variant_id, quantity) select v.id, x.stock from v join (values ('MOCK-OLIVE-OIL-1',40), ('MOCK-OLIVE-OIL-2',12)) as x(sku, stock) using (sku);
